#include <stdio.h>

// Swapping values by manipulating caller's memory directly
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int x = 10, y = 20;
    swap(&x, &y);
    printf("Swapped: x=%d, y=%d\n", x, y);
    return 0;
}

