#include <stdio.h>
#include <stdlib.h>

int main() {
    int *arr = (int*)malloc(2 * sizeof(int));
    arr[0] = 100; arr[1] = 200;

    // Expand buffer capacity dynamically to 4 ints
    int *temp = (int*)realloc(arr, 4 * sizeof(int));
    if (temp != NULL) {
        arr = temp;
        arr[2] = 300; arr[3] = 400;
        printf("Expanded Array item 3: %d\n", arr[3]);
    }

    free(arr);
    arr = NULL; // Prevent dangling pointer
    return 0;
}

